#pragma once

// Colormap lookup tables and the dB -> RGBA column helper (spec:. The Spectrogram module
// turns each analysed column of dB values into texture pixels with these.
//
// Magma, Viridis and Inferno data come from matplotlib's listed colormaps.
// They are CC0, by Nathaniel J. Smith, Stéfan van der Walt and Eric Firing.
// The tables are generated by modules/common/tools/gen_colormaps.py into
// dsp_common/src/colormap_data.inl (committed, so builds need no Python).
// Grey is linear 0 -> 255.
//
// Packing: rgba = R | G<<8 | B<<16 | A<<24 with A = 255. The bytes in memory
// are therefore R, G, B, A, which matches DXGI_FORMAT_R8G8B8A8_UNORM and
// ImGui IM_COL32.
//
// All functions are noexcept and allocation-free: safe on real-time paths
// and from any thread (the tables are immutable constants).

#include <array>
#include <cstddef>
#include <cstdint>

namespace dsptb::dsp {

enum class Colormap : std::uint8_t { Magma, Viridis, Inferno, Grey };

// The 256-entry packed-RGBA lookup table for a colormap. Entry i is the
// colour at t = i/255. The returned reference names a static constant table:
// it stays valid for the life of the program and is identical on every call
// for the same colormap.
const std::array<std::uint32_t, 256>& colormapLut(Colormap map) noexcept;

// The colour at t01 in [0, 1]: t01 is clamped to that range and the nearest
// LUT entry is returned (index = round(255 * t)). A NaN t01 maps to entry 0,
// so a bad value renders as the bottom of the scale rather than as garbage.
std::uint32_t colormapRgba(Colormap map, float t01) noexcept;

// Convert n dB values to packed RGBA pixels: out[i] is the colormap colour
// for db[i] normalised as (db[i] - minDb) / (maxDb - minDb), clamped to the
// table ends. Values <= minDb map to entry 0, values >= maxDb to entry 255,
// and NaN maps to entry 0. dB here is the caller's display range (the
// Spectrogram uses its min_db / max_db parameters, both in dB); this helper
// only rescales, it does not interpret the dB reference. Passing
// maxDb <= minDb is a degenerate range: every non-NaN value at or above
// maxDb then maps to entry 255 and every value below it to entry 0.
// Null db or out pointers are a no-op. No allocation, no locks, no throws.
void dbToRgba(const float* db, std::size_t n, float minDb, float maxDb, Colormap map,
              std::uint32_t* out) noexcept;

} // namespace dsptb::dsp
